// Real local processes, sockets, files, independent CLI clients; no runtime mocks.
import * as fs from 'node:fs';
import * as path from 'node:path';
import os from 'node:os';
import net from 'node:net';
import assert from 'node:assert/strict';
import {spawn} from 'node:child_process';
import {randomUUID} from 'node:crypto';
import {openPlot} from '../main.js';
import {start,request,recover,prune,fence} from '../capabilities/resident.mjs';
const base=path.resolve(new URL('..',import.meta.url).pathname),core=path.join(base,'main.js'),module=path.join(base,'capabilities/resident.mjs'),node=process.execPath;
const tmp=fs.mkdtempSync(path.join(os.tmpdir(),'plot-resident-')),checks=[],started=new Date().toISOString(),services=new Set();
const read=p=>JSON.parse(fs.readFileSync(p));
const sleep=ms=>new Promise(r=>setTimeout(r,ms));
async function until(fn,ms=12000){const end=Date.now()+ms;let last;while(Date.now()<end){try{const r=await fn();if(r)return r}catch(e){last=e}await sleep(20)}throw last||Error('condition deadline')}
// A seed-coupled check reports {pending} only after observing that the seed lacks the coupled feature;
// PLOT_REQUIRE_SEED_COUPLED=1 turns every pending check into a failure.
const pending=[];
const test=async(name,fn)=>{const t=performance.now();try{const evidence=await fn();if(evidence?.pending){pending.push({name,ms:performance.now()-t,...evidence});console.log('PENDING '+name+' ('+evidence.pending+'): '+evidence.observed);return}checks.push({name,passed:true,ms:performance.now()-t,...(evidence?{evidence}:{})});console.log('PASS '+name)}catch(e){checks.push({name,passed:false,error:e.stack});console.error('FAIL '+name+'\n'+e.stack)}};
function fixture(name,m={}){const root=path.join(tmp,name);fs.mkdirSync(root);fs.mkdirSync(path.join(root,'capabilities'));fs.copyFileSync(module,path.join(root,'capabilities/resident.mjs'));writeManifest(root,m);return root}
function writeManifest(root,m={}){fs.writeFileSync(path.join(root,'manifest.json'),JSON.stringify({hosts:['node'],execution:'trusted',permissions:{spawn:true},capabilities:{resident:{install:[{cmd:node,args:['-e',"require('node:fs').copyFileSync(process.argv[1],'resident.mjs')",path.join(root,'capabilities/resident.mjs')]}]},...m.capabilities},environment:{use:[]},steps:[],...m,...(m.capabilities?{capabilities:{resident:{install:[{cmd:node,args:['-e',"require('node:fs').copyFileSync(process.argv[1],'resident.mjs')",path.join(root,'capabilities/resident.mjs')]}]},...m.capabilities}}:{})}))}
function child(args,options={}){const c=spawn(node,args,{stdio:['pipe','pipe','pipe'],...options});let stdout='',stderr='';c.stdout?.on('data',b=>stdout+=b);c.stderr?.on('data',b=>stderr+=b);const done=new Promise((r,j)=>{c.once('error',j);c.once('close',(code,signal)=>r({code,signal,stdout,stderr}))});return {c,done}}
async function client(root,args,body){const c=child([module,'--root',root,...args]);c.c.stdin.end(body?JSON.stringify(body):undefined);const r=await c.done;if(r.code!==0)throw Error(r.stderr||r.stdout);return JSON.parse(r.stdout)}
async function server(root,env={}){const c=child([module,'--serve',root,core],{env:{...process.env,...env}});c.c.stdin.end();services.add(c);const e=await until(async()=>{const e=read(path.join(root,'.grave/resident/service.json'));await request(e,{op:'ping'},300);return e});return {...c,e}}
async function stop(s){try{await request(s.e,{op:'stop'})}catch{}await s.done;services.delete(s)}
async function submit(e,code,extra={}){return request(e,{op:'submit',name:'native',steps:[{cmd:node,args:['-e',code]}],...extra})}
async function done(e,id){return until(async()=>{const s=await request(e,{op:'inspect',id});return ['succeeded','failed','cancelled','timed_out','interrupted'].includes(s.state)&&s},20000)}
const recipe=value=>({install:[{cmd:node,args:['-e',`require('node:fs').writeFileSync('value',${JSON.stringify(value)})`]}]});
try{
 await test('optional capability acquisition and native-only clean CLI startup',async()=>{const root=fixture('optional');await openPlot(root).provision('native',{use:[]});const e=await start(root,core);assert.ok(read(path.join(root,'data.json')).assets.resident);assert.ok(!read(path.join(root,'data.json')).assets.python);assert.ok(fs.existsSync(path.join(read(path.join(root,'data.json')).assets.resident.path,'resident.mjs')));const {id}=await submit(e,'console.log("native ready")');assert.equal((await done(e,id)).state,'succeeded');assert.match((await request(e,{op:'output',id})).text,/native ready/);await request(e,{op:'stop'});return {pythonRequired:false,acquiredResident:true}});
 await test('concurrent start clients converge on one authenticated supervisor',async()=>{const r=fixture('concurrent-start');const out=await Promise.all(Array.from({length:3},()=>client(r,['start'])));assert.equal(new Set(out.map(x=>x.instance)).size,1);const endpoint=read(path.join(r,'.grave/resident/service.json'));await request(endpoint,{op:'stop'});await sleep(100);return {clients:3,supervisors:1}});
 const root=fixture('jobs');await openPlot(root).provision('native',{use:[]});let s=await server(root),e=s.e;
 await test('job outlives submitting CLI; a distinct CLI discovers identity, status and output',async()=>{const job=await client(root,['submit','native',node,'-e',`console.log('before disconnect');setTimeout(()=>{console.log('after disconnect');require('node:fs').writeFileSync(process.env.PLOT_STATE+'/survived','yes')},700)`]);assert.ok(job.id);const listed=await client(root,['list']);assert.ok(listed.jobs.some(j=>j.id===job.id));const final=await done(e,job.id);assert.equal(final.state,'succeeded');const out=await client(root,['output',job.id]);assert.equal(out.text,'before disconnect\nafter disconnect\n');assert.equal(fs.readFileSync(path.join(root,'.grave/work/native/survived'),'utf8'),'yes');return {id:job.id,submittingClientExited:true,reconnectedClient:true,status:final.state,output:out.text}});
 await test('abrupt transport disconnect after submission does not cancel accepted work',async()=>{const id='drop-'+randomUUID();await new Promise((resolve,reject)=>{const c=net.createConnection({host:'127.0.0.1',port:e.port});c.on('error',reject);c.on('connect',()=>{c.write(JSON.stringify({token:e.token,op:'submit',id,name:'native',steps:[{cmd:node,args:['-e',"setTimeout(()=>console.log('transport survived'),200)"]}]})+'\n',()=>{c.destroy();resolve()})})});await until(async()=>{const l=await client(root,['list']);return l.jobs.some(j=>j.id===id)});assert.equal((await done(e,id)).state,'succeeded');assert.equal((await client(root,['output',id])).text,'transport survived\n');return {id,transportClosedBeforeResponse:true}});
 await test('concurrent clients, stable identities and exactly one job for retried submission',async()=>{const ids=await Promise.all(Array.from({length:8},(_,i)=>client(root,['request'],{op:'submit',id:'concurrent-'+i,name:'native',steps:[{cmd:node,args:['-e',`console.log(${i});setTimeout(()=>{},100)`]}]})));assert.equal(new Set(ids.map(j=>j.id)).size,8);for(const j of ids)assert.equal((await done(e,j.id)).state,'succeeded');const id='retry-'+randomUUID(),body={op:'submit',id,name:'native',steps:[{cmd:node,args:['-e','console.log("once")']}]};const [a,b]=await Promise.all([request(e,body),request(e,body)]);assert.equal(a.id,b.id);assert.equal((await done(e,id)).state,'succeeded');assert.equal((await request(e,{op:'output',id})).text,'once\n');await assert.rejects(request(e,{...body,steps:[]}),/different request/);return {clients:8,retries:2,singleExecution:true}});
 await test('supervisor SIGKILL/restart reconnects to an already running independent worker',async()=>{const {id}=await submit(e,"console.log('worker alive');setTimeout(()=>console.log('worker finished'),1600)");await until(async()=>{const t=await request(e,{op:'inspect',id});return t.state==='running'&&t});const before=read(path.join(root,'.grave/resident/jobs',id,'control.json'));const oldInstance=e.instance;s.c.kill('SIGKILL');await s.done;services.delete(s);s=await server(root);e=s.e;assert.notEqual(e.instance,oldInstance);const final=await done(e,id);assert.equal(final.state,'succeeded');assert.equal(final.instance,before.instance);assert.match((await request(e,{op:'output',id})).text,/worker finished/);return {id,workerInstance:before.instance,state:final.state}});
 await test('exact frozen view, executable, environment, literal commands and dependencies survive changes',async()=>{const r=fixture('snapshot',{capabilities:{data:recipe('old')}}),p=openPlot(r);const old=await p.provision('native',{use:['data']});const v=await server(r);try{const {id}=await request(v.e,{op:'submit',name:'native',steps:[{cmd:node,needs:['data'],env:{MARK:'saved'},args:['-e',`setTimeout(()=>{console.log(require('node:fs').readFileSync(process.argv[1],'utf8'));console.log(process.env.MARK);console.log(process.argv[2])},500)`,'${cap:data}/value','$(touch NEVER)']}]});writeManifest(r,{capabilities:{data:recipe('new')},steps:[{cmd:'invalid',args:[]}]});const next=await p.provision('native',{use:['data']});assert.notEqual(old.assets.data.path,next.assets.data.path);const final=await done(v.e,id);assert.equal(final.state,'succeeded');assert.equal(final.spec.view.assets.data.path,old.assets.data.path);assert.equal(final.spec.steps[0].cmd,fs.realpathSync(node));assert.equal(final.spec.steps[0].options.env.MARK,'saved');assert.equal(final.spec.source[0].needs[0],'data');assert.equal(final.spec.source[0].cmd,node);assert.equal((await request(v.e,{op:'output',id})).text,'old\nsaved\n$(touch NEVER)\n');assert.ok(!fs.existsSync(path.join(r,'NEVER')));return {oldObjectRetained:true,snapshotExecuted:true}}finally{await stop(v)}});
 await test('persistent Python jobs retain conflicting package views while reusing one runtime',async()=>{const {python,wheels}=await import('./helpers.mjs');const wheelDir=path.join(tmp,'real-wheels');fs.mkdirSync(wheelDir);const dist=wheels(wheelDir),r=fixture('persistent-python',{tenants:{python:{command:python,packages:[dist.one],pip:['--no-index']}}}),p=openPlot(r);const one=await p.provision('one',{use:['python-packages']}),two=await p.provision('two',{use:['python-packages'],python:{packages:[dist.two]}});assert.equal(one.python,two.python);assert.notEqual(one.packages,two.packages);const v=await server(r);try{const jobs=await Promise.all(['one','two'].map(name=>request(v.e,{op:'submit',name,steps:[{cmd:'python',args:['-c','import plot_sample;print(plot_sample.VERSION)']}]})));for(let i=0;i<2;i++){const final=await done(v.e,jobs[i].id);assert.equal(final.state,'succeeded');assert.equal((await request(v.e,{op:'output',id:jobs[i].id})).text,(i+1)+'.0\n');assert.equal(final.spec.view.python,one.python)}return {sharedRuntime:true,isolatedVersions:['1.0','2.0']}}finally{await stop(v)}});
 await test('bounded binary stdout/stderr, byte cursors, timeout, cancellation and step failure',async()=>{let j=await submit(e,"process.stdout.write(Buffer.alloc(100000,65));process.stderr.write('tail')",{limits:{outputBytes:4096}});let t=await done(e,j.id);assert.equal(t.state,'succeeded');assert.equal(t.bytes,4096);assert.equal(t.outputLimited,true);const out=await request(e,{op:'output',id:j.id,offset:4000,bytes:500});assert.equal(out.next,4096);assert.equal(Buffer.from(out.dataBase64,'base64').length,96);await assert.rejects(request(e,{op:'output',id:j.id,offset:-1}),/range/);j=await submit(e,'setInterval(()=>{},100)',{limits:{timeoutMs:200}});assert.equal((await done(e,j.id)).state,'timed_out');j=await submit(e,"process.on('SIGTERM',()=>{});console.log('ready');setInterval(()=>{},100)");await until(async()=>/ready/.test((await request(e,{op:'output',id:j.id})).text));await request(e,{op:'cancel',id:j.id});assert.equal((await done(e,j.id)).state,'cancelled');j=await request(e,{op:'submit',name:'native',steps:[{cmd:node,args:['-e','process.exit(7)']},{cmd:node,args:['-e','console.log("BAD")']}]});t=await done(e,j.id);assert.equal(t.exitCode,7);assert.equal(t.state,'failed');assert.equal((await request(e,{op:'output',id:j.id})).text,'');j=await submit(e,"process.kill(process.pid,'SIGTERM')");assert.equal((await done(e,j.id)).state,'failed')});
 await test('missing capability, authority denial, unauthenticated calls and invalid requests fail closed',async()=>{await assert.rejects(request({...e,token:'wrong'},{op:'submit'}),/unauthorized/);await assert.rejects(request(e,{op:'submit',name:'native',steps:[{cmd:node,needs:['absent'],args:[]}]}),/missing capability/);await assert.rejects(submit(e,'',{limits:{outputBytes:Infinity}}),/invalid limits/);await assert.rejects(submit(e,'',{id:'../escape'}),/identity/);await assert.rejects(request(e,{op:'submit',name:'native',steps:[{cmd:'definitely-no-such-program',args:[]}]}),/executable unavailable/);writeManifest(root,{permissions:{spawn:false}});await assert.rejects(submit(e,''),/trusted/);const list=await request(e,{op:'list'});assert.ok(list.jobs.length);writeManifest(root)});
 await test('stale records never authorize signalling an unrelated live process',async()=>{const unrelated=child(['-e',"console.log('alive');setInterval(()=>{},100)"]);unrelated.c.stdin.end();try{const id='stale-'+randomUUID(),d=path.join(root,'.grave/resident/jobs',id);fs.mkdirSync(d);fs.writeFileSync(path.join(d,'submission.json'),JSON.stringify({id,created:new Date().toISOString(),request:{},spec:{}}));fs.writeFileSync(path.join(d,'status.json'),JSON.stringify({id,state:'running',pid:unrelated.c.pid}));fs.writeFileSync(path.join(d,'owner.json'),JSON.stringify({pid:unrelated.c.pid,birth:'wrong-incarnation'}));const st=await request(e,{op:'inspect',id});assert.ok(['interrupted','unreachable'].includes(st.state));await assert.rejects(request(e,{op:'cancel',id}));assert.equal(unrelated.c.exitCode,null);return {state:st.state,unrelatedProcessUntouched:true}}finally{unrelated.c.kill('SIGTERM');await unrelated.done}});
 await test('worker crash becomes interrupted/unreachable; no success fabricated or step replayed',async()=>{const file=path.join(root,'orphan-result');const j=await submit(e,`require('node:fs').appendFileSync(${JSON.stringify(file)},'once');process.kill(process.ppid,'SIGKILL');setTimeout(()=>{},100)`);const st=await until(async()=>{const t=await request(e,{op:'inspect',id:j.id});return ['interrupted','unreachable'].includes(t.state)&&fs.existsSync(file)&&t});await sleep(250);assert.equal(fs.readFileSync(file,'utf8'),'once');await assert.rejects(request(e,{op:'cancel',id:j.id}));assert.ok(!['succeeded','failed'].includes(st.state));return {id:j.id,state:st.state,executions:1}});
 await test('acquisition crash reconciliation retains incomplete objects, committed views and owned state',async()=>{const r=fixture('recovery',{capabilities:{data:recipe('stable')}}),p=openPlot(r);const view=await p.provision('native',{use:['data']});fs.writeFileSync(path.join(view.state,'saved'),'keep');const marker=path.join(r,'installer-started');writeManifest(r,{environment:{use:['data']},capabilities:{data:{install:[{cmd:node,args:['-e',`require('node:fs').writeFileSync(${JSON.stringify(marker)},'yes');setTimeout(()=>{},700)`]}]}}});const acquisition=child([core,'--root',r,'provision','native']);acquisition.c.stdin.end();await until(()=>fs.existsSync(marker));const lock=read(path.join(r,'.grave/.lock/owner.json'));assert.equal(lock.stages.length,1);acquisition.c.kill('SIGKILL');await acquisition.done;const result=recover(r);assert.equal(result.state,'reconciled');assert.ok(fs.existsSync(lock.stages[0]));assert.deepEqual(p.view('native'),JSON.parse(JSON.stringify(view)));assert.equal(fs.readFileSync(path.join(view.state,'saved'),'utf8'),'keep');await sleep(750);const v=await p.provision('native',{use:['data']});assert.notEqual(v.assets.data.path,view.assets.data.path);assert.ok(fs.existsSync(view.assets.data.path));assert.ok(fs.existsSync(path.join(r,'data.json')));return {reconciliation:result.state,incompleteRetained:true,viewRetained:true,noSignals:true}});
 await test('damaged job records remain visible and cannot hide healthy jobs',async()=>{const id='damaged-'+randomUUID(),d=path.join(root,'.grave/resident/jobs',id);fs.mkdirSync(d);fs.writeFileSync(path.join(d,'submission.json'),'{broken');const page=await request(e,{op:'list'});assert.equal(page.jobs.find(x=>x.id===id).state,'record_error');assert.ok(page.jobs.some(x=>x.state==='succeeded'));await assert.rejects(request(e,{op:'cancel',id}));fs.rmSync(d,{recursive:true})});
 await test('cancellation owns the direct child and bounds inherited-pipe waiting',async()=>{const marker=path.join(root,'descendant-finished'),code="require('node:child_process').spawn(process.execPath,['-e',"+JSON.stringify('setTimeout(()=>require("node:fs").writeFileSync('+JSON.stringify(marker)+',"yes"),1100)')+"],{stdio:['ignore','inherit','inherit']}).unref();console.log('parent-ready');setInterval(()=>{},100)";const j=await submit(e,code);await until(async()=>/parent-ready/.test((await request(e,{op:'output',id:j.id})).text));await request(e,{op:'cancel',id:j.id});const final=await done(e,j.id);assert.equal(final.state,'cancelled');assert.equal(final.inheritedPipesClosed,true);await until(()=>fs.existsSync(marker));return {directChildCancelled:true,descendantNotSignalled:true}});
 await test('legacy unstamped locks and ambiguous live writers remain blocked',async()=>{const r=fixture('legacy'),lock=path.join(r,'.grave/.lock');fs.mkdirSync(lock,{recursive:true});assert.equal(recover(r).state,'unknown');fs.writeFileSync(path.join(lock,'owner.json'),JSON.stringify({pid:process.pid,stages:[]}));assert.equal(recover(r).state,'blocked');await assert.rejects(openPlot(r).provision(),/busy/);assert.ok(fs.existsSync(lock))});
 await test('failed resident acquisition rolls back; disconnected provisioning client does not cancel writer',async()=>{const r=fixture('remote-acquire',{capabilities:{bad:{install:[{cmd:node,args:['-e','process.exit(13)']}]},slow:{install:[{cmd:node,args:['-e',"setTimeout(()=>require('node:fs').writeFileSync('ready','yes'),400)"]}]}}}),v=await server(r);try{await assert.rejects(request(v.e,{op:'provision',name:'bad',spec:{use:['bad']}}),/exec/);assert.ok(!fs.existsSync(path.join(r,'data.json')));const c=child([module,'--root',r,'provision','slow','{"use":["slow"]}']);c.c.stdin.end();await until(()=>fs.existsSync(path.join(r,'.grave/.lock/owner.json')));c.c.kill('SIGKILL');await c.done;await until(()=>fs.existsSync(path.join(r,'.grave/envs/slow.json')));assert.equal(fs.readFileSync(path.join(openPlot(r).view('slow').assets.slow.path,'ready'),'utf8'),'yes');return {clientKilled:true,viewCommitted:true}}finally{await stop(v)}});
 await test('cold acquisition continues through supervisor death and restart',async()=>{const r=fixture('acquisition-supervisor',{environment:{use:['slow']},capabilities:{slow:{install:[{cmd:node,args:['-e',"setTimeout(()=>require('node:fs').writeFileSync('acquired','yes'),700)"]}]}}});let v=await server(r);try{const pending=request(v.e,{op:'provision',name:'native',spec:{use:['slow']}}).catch(()=>null);await until(()=>fs.existsSync(path.join(r,'.grave/.lock/owner.json')));v.c.kill('SIGKILL');await v.done;services.delete(v);v=await server(r);await until(()=>fs.existsSync(path.join(r,'.grave/envs/native.json')));const view=openPlot(r).view('native');assert.equal(fs.readFileSync(path.join(view.assets.slow.path,'acquired'),'utf8'),'yes');await pending;await until(()=>fs.readdirSync(path.join(r,'.grave/resident/acquisitions')).some(n=>n.endsWith('.json')&&read(path.join(r,'.grave/resident/acquisitions',n)).state==='succeeded'));const recovered=await request(v.e,{op:'recover'});assert.equal(recovered.state,'clear');assert.ok(recovered.acquisitions.some(x=>x.state==='succeeded'));return {supervisorKilled:true,acquisitionCommitted:true}}finally{await stop(v)}});
 await test('supervisor stop leaves submitted job running and status available after restart',async()=>{const j=await submit(e,"console.log('continuing');setTimeout(()=>console.log('continued'),700)");await until(async()=>{let t=await request(e,{op:'inspect',id:j.id});return t.state==='running'});await stop(s);s=await server(root);e=s.e;assert.equal((await done(e,j.id)).state,'succeeded');assert.match((await request(e,{op:'output',id:j.id})).text,/continued/)});
 const stateOf=(r,id)=>{try{return read(path.join(r,'.grave/resident/jobs',id,'status.json'))}catch{return null}};
 function tree(dir,skip=[]){const out={},walk=(d,rel)=>{for(const n of fs.readdirSync(d).sort()){const p=path.join(d,n),q=rel?rel+'/'+n:n;if(skip.includes(q))continue;const st=fs.lstatSync(p);if(st.isDirectory()){out[q+'/']=st.mode;walk(p,q)}else out[q]=fs.readFileSync(p,'utf8')}};walk(dir,'');return out}
 const grave=r=>tree(path.join(r,'.grave'),['resident']);
